    assert_eq!(parsed["provider"], "custom");
    assert!(parsed["environment"].is_object());
    assert!(parsed["plan"].is_object());
    assert_eq!(
        parsed["result"]["steps"].as_array().map(std::vec::Vec::len),
        Some(3)
    );
