#[test]
fn doctor_relational_integrity_diagnostics_prefers_canonical_engine() {
    // css/ts2 startup-wedge regression guard: the relational battery on the
    // startup self-heal path MUST run on the canonical (real-SQLite) engine,
    // not the bespoke FrankenSQLite engine whose PRAGMA foreign_key_check is
    // O(child_rows × parent_lookup) and pegged a CPU core for minutes on a
    // large mailbox (the interactive server/TUI looked hung). Verdicts are
    // preserved (the orphaned recipient is still detected) and the evidence
    // proves the canonical engine ran.
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("relational_engine.sqlite3");
    seed_startup_self_heal_fk_orphan(&db_path);
    let conn = mcp_agent_mail_db::DbConn::open_file(db_path.display().to_string())
        .expect("open bespoke conn");
    let diagnostics =
        doctor_relational_integrity_diagnostics(&conn, &db_path).expect("relational diagnostics");
    assert!(
        !diagnostics.orphaned_recipients.is_empty(),
        "the orphaned recipient must still be detected (verdict preserved)"
    );
    let detail = doctor_relational_integrity_detail_prefix(&diagnostics);
    assert!(
        detail.contains("canonical_sqlite"),
        "startup relational diagnostics must run on the canonical engine, not the bespoke \
             O(n²) engine; evidence: {detail}"
    );
}

/// br-mdfpz: seed a real-schema mailbox DB whose archive identity matches
/// (so archive drift is not authoritative), then corrupt ONLY the
/// `idx_agents_project_name` index b-tree by flipping one payload byte in
/// an index cell — the table b-trees stay intact, `foreign_key_check`
/// stays clean, and a full `integrity_check` reports only
/// index-class rows (`row N missing from index ...`).
fn seed_index_only_corrupt_mailbox(db_path: &Path) {
    let db_path_text = db_path.display().to_string();
    init_schema_sqlite_canonical(&db_path_text).expect("init schema");
    {
        let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(&db_path_text)
            .expect("open canonical fixture db");
        conn.query_sync(
                "INSERT INTO projects (id, slug, human_key, created_at) VALUES (1, 'ahead-project', '/ahead-project', 0)",
                &[],
            )
            .expect("insert archive-matching project");
        for i in 1..=50i64 {
            conn.query_sync(
                    &format!(
                        "INSERT INTO agents (id, project_id, name, program, model, inception_ts, last_active_ts) \
                         VALUES ({i}, 1, 'ReindexAgent{i:02}', 'coder', 'test', 0, 0)"
                    ),
                    &[],
                )
                .expect("insert agent row");
        }
        conn.execute_raw("PRAGMA wal_checkpoint(TRUNCATE)")
            .expect("checkpoint fixture db");
    }
    let root_page = {
        let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(&db_path_text)
            .expect("reopen for rootpage lookup");
        let rows = conn
            .query_sync(
                "SELECT rootpage FROM sqlite_master WHERE name = 'idx_agents_project_name'",
                &[],
            )
            .expect("query index rootpage");
        let root: i64 = rows
            .first()
            .and_then(|row| row.get_as(0).ok())
            .expect("index rootpage row");
        usize::try_from(root).expect("rootpage fits usize")
    };
    let mut bytes = std::fs::read(db_path).expect("read fixture db bytes");
    let raw_page_size = u16::from_be_bytes([bytes[16], bytes[17]]);
    let page_size = if raw_page_size == 1 {
        65_536usize
    } else {
        usize::from(raw_page_size)
    };
    let page_start = (root_page - 1) * page_size;
    let page = &bytes[page_start..page_start + page_size];
    let needle = b"ReindexAgent";
    let hit = page
        .windows(needle.len())
        .skip(16)
        .position(|window| window == needle)
        .expect("index page must contain an agent-name key")
        + 16;
    // Flip one key byte inside the index cell: the table row's key no
    // longer matches its index entry, and nothing else in the file changes.
    bytes[page_start + hit + 7] ^= 0x01;
    std::fs::write(db_path, &bytes).expect("write corrupted index page");
}

#[test]
fn index_only_reindex_expands_index_witnesses_to_distinct_owner_tables() {
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("owner-tables.sqlite3");
    let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(db_path.display().to_string())
        .expect("open fixture db");
    conn.execute_raw("CREATE TABLE alpha (id INTEGER PRIMARY KEY, left_key TEXT, right_key TEXT)")
        .expect("create alpha");
    conn.execute_raw("CREATE INDEX idx_alpha_left ON alpha(left_key)")
        .expect("create first alpha index");
    conn.execute_raw("CREATE INDEX idx_alpha_right ON alpha(right_key)")
        .expect("create second alpha index");
    conn.execute_raw("CREATE TABLE beta (id INTEGER PRIMARY KEY, lookup_key TEXT)")
        .expect("create beta");
    conn.execute_raw("CREATE INDEX idx_beta_lookup ON beta(lookup_key)")
        .expect("create beta index");

    let tables = doctor_index_owner_tables_for_damage(
        &conn,
        &[
            "idx_beta_lookup".to_string(),
            "idx_alpha_left".to_string(),
            "idx_alpha_right".to_string(),
        ],
    )
    .expect("resolve owner tables");
    assert_eq!(tables, vec!["alpha", "beta"]);
    assert!(
        doctor_index_owner_tables_for_damage(&conn, &["missing_index".to_string()]).is_err(),
        "unknown diagnostic witnesses must not silently narrow table-wide repair"
    );
}

#[test]
fn startup_database_self_heal_reindexes_index_only_corruption_without_reconstruct() {
    let dir = tempfile::tempdir().expect("tempdir");
    seed_archive_mailbox_project(dir.path());
    let db_path = dir.path().join("storage.sqlite3");
    let db_url = format!("sqlite:///{}", db_path.display());
    seed_index_only_corrupt_mailbox(&db_path);

    // The fixture must classify as index-only damage...
    let opened = doctor_open_canonical_source_for_diagnostic(&db_path, "fixture probe")
        .expect("readonly probe open");
    assert!(
        !opened.is_live_logical_snapshot(),
        "sidecarless canonical fixture must use the guarded offline authority"
    );
    let conn = &opened.conn;
    let rows = sqlite_query_check_rows(
        |sql| conn.query_sync(sql, &[]).map_err(|e| e.to_string()),
        mcp_agent_mail_db::CheckKind::Full,
    )
    .expect("integrity rows");
    let details = mcp_agent_mail_db::integrity::extract_check_details(
        &rows,
        mcp_agent_mail_db::CheckKind::Full,
    );
    assert!(
        !mcp_agent_mail_db::integrity::details_indicate_ok(&details),
        "fixture integrity_check must fail: {details:?}"
    );
    let damaged = mcp_agent_mail_db::integrity::index_only_corruption_index_names(&details)
        .unwrap_or_else(|| panic!("fixture damage must be index-only: {details:?}"));
    assert_eq!(damaged, vec!["idx_agents_project_name"]);
    drop(opened);

    // ...and route the startup strategy to the (lossy-prone) reconstruct arm.
    let action = startup_database_self_heal_action(&db_url, dir.path())
        .expect("classify startup database issue");
    assert!(
        matches!(action, StartupDatabaseSelfHealAction::Reconstruct(_)),
        "index corruption with an authoritative archive must classify as reconstruct: {action:?}"
    );

    let reconstruct_called = std::cell::Cell::new(false);
    run_startup_database_self_heal_with(
        &db_url,
        dir.path(),
        || panic!("index-only corruption must not run the repair subprocess"),
        |_| {
            reconstruct_called.set(true);
            Ok(())
        },
    )
    .expect("startup self-heal should succeed via the REINDEX fast path");

    assert!(
        !reconstruct_called.get(),
        "REINDEX fast path must heal index-only corruption without archive reconstruction"
    );
    match doctor_database_fix_strategy(&db_url, dir.path()).expect("post-heal strategy") {
        DoctorDatabaseFixStrategy::None(_) => {}
        other => panic!("post-REINDEX strategy should be clean: {other:?}"),
    }
    // Zero row loss and a pre-reindex backup exists.
    let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(db_path.display().to_string())
        .expect("reopen healed db");
    let rows = conn
        .query_sync("SELECT COUNT(*) AS c FROM agents", &[])
        .expect("count agents");
    let agents: i64 = rows
        .first()
        .and_then(|row| row.get_named("c").ok())
        .unwrap_or(-1);
    assert_eq!(agents, 50, "REINDEX must not lose table rows");
    let backups: Vec<_> = std::fs::read_dir(dir.path().join("backups"))
        .expect("backups dir")
        .flatten()
        .filter(|entry| {
            entry
                .file_name()
                .to_string_lossy()
                .contains(".pre-reindex-")
        })
        .collect();
    assert!(
        !backups.is_empty(),
        "REINDEX fast path must capture a pre-reindex backup"
    );
}

#[test]
fn read_only_live_logical_snapshot_cannot_hide_primary_index_corruption() {
    let dir = tempfile::tempdir().expect("tempdir");
    seed_archive_mailbox_project(dir.path());
    let db_path = dir.path().join("storage.sqlite3");
    let db_url = format!("sqlite:///{}", db_path.display());
    seed_index_only_corrupt_mailbox(&db_path);

    // Admit the existing generation through FrankenSQLite so the doctor
    // must use its live-family path. A table scan remains readable even
    // though the physical secondary-index b-tree is damaged.
    let admitted = mcp_agent_mail_db::DbConn::open_file(db_path.display().to_string())
        .expect("admit corrupt-index fixture through FrankenSQLite");
    let rows = admitted
        .query_sync("SELECT COUNT(*) AS count FROM agents", &[])
        .expect("table b-tree remains readable");
    assert_eq!(rows[0].get_named::<i64>("count").expect("count"), 50);
    mcp_agent_mail_db::close_db_conn(admitted, "settle live Franken index-corruption fixture");

    let logical_is_healthy = with_private_canonical_snapshot_from_live_franken(
        &db_path,
        "index-corruption logical export control",
        |snapshot| {
            sqlite_conn_check_ok_canonical(snapshot, mcp_agent_mail_db::CheckKind::Full)
                .map_err(|error| CliError::Other(error.to_string()))
        },
    )
    .expect("check actual rebuilt logical image");
    assert!(
        logical_is_healthy,
        "VACUUM rebuild should normalize the damaged secondary index in the private image"
    );

    let opened = open_db_for_doctor_check_read_only_with_context(&db_url)
        .expect("stage guarded live physical family");
    assert_eq!(
        opened.source_kind,
        DoctorCanonicalDiagnosticSourceKind::StagedFamilyCopy
    );
    assert!(
        !sqlite_conn_check_ok_canonical(&opened.conn, mcp_agent_mail_db::CheckKind::Full)
            .expect("check physical family copy"),
        "the staged copy must preserve the damaged secondary index"
    );
    assert!(
        !doctor_read_only_physical_integrity_check(&opened, mcp_agent_mail_db::CheckKind::Full)
            .expect("run admitted live physical check"),
        "the live physical index defect must remain authoritative"
    );
    drop(opened);

    match doctor_database_fix_strategy_read_only(&db_url, dir.path())
        .expect("classify live physical index corruption")
    {
        DoctorDatabaseFixStrategy::Repair(_) | DoctorDatabaseFixStrategy::Reconstruct(_) => {}
        DoctorDatabaseFixStrategy::None(detail) => panic!(
            "a clean logical snapshot must not make startup skip the admitted physical re-probe: {detail}"
        ),
    }
    let repair_plan = doctor_classify_index_only_repair(&db_path)
        .expect("classify the live physical index defect");
    assert_eq!(repair_plan.engine, DoctorIndexRepairEngine::LiveFranken);
    assert_eq!(repair_plan.damaged_indexes, vec!["idx_agents_project_name"]);

    let repair_called = std::cell::Cell::new(false);
    let reconstruct_called = std::cell::Cell::new(false);
    run_startup_database_self_heal_with(
        &db_url,
        dir.path(),
        || {
            repair_called.set(true);
            Ok(())
        },
        |_| {
            reconstruct_called.set(true);
            Ok(())
        },
    )
    .expect("live Franken index damage should heal through matching-engine REINDEX");
    assert!(
        !repair_called.get() && !reconstruct_called.get(),
        "matching-engine REINDEX must complete before either lossy recovery callback"
    );
    assert!(
        doctor_index_repair_live_franken_is_healthy(&db_path),
        "the live Franken physical family must pass full relational/schema verification"
    );
    match doctor_database_fix_strategy(&db_url, dir.path()).expect("post-REINDEX strategy") {
        DoctorDatabaseFixStrategy::None(_) => {}
        other => panic!("matching-engine REINDEX must leave a healthy/None verdict: {other:?}"),
    }
}

/// br-s9d8a: a sidecar-free family left with WAL frames and an SHM by a
/// canonical writer (a Python-era mailbox at rest) cannot be opened by
/// the guarded read-only opener; the doctor's canonical source selection
/// must fall back to the private staged copy, see the WAL-only rows there,
/// and leave every source-family byte untouched.
#[test]
fn doctor_canonical_source_selection_stages_a_resting_wal_family() {
    // The shape the guarded read-only opener cannot serve: a WAL with
    // committed frames whose SHM is missing (a crashed canonical writer,
    // or a family copied without its SHM). A read-only SHM cannot be
    // rebuilt, so the open fails eagerly and the selection must fall back
    // to the private staged copy, which applies the WAL in the copy.
    let writer_dir = tempfile::tempdir().expect("writer tempdir");
    let writer_path = writer_dir.path().join("resting-wal.sqlite3");
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("resting-wal.sqlite3");
    {
        let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(writer_path.display().to_string())
            .expect("seed canonical WAL family");
        conn.execute_raw("PRAGMA journal_mode = WAL; PRAGMA wal_autocheckpoint = 0;")
            .expect("enable WAL without automatic checkpoints");
        conn.execute_raw("CREATE TABLE t (id INTEGER PRIMARY KEY); INSERT INTO t (id) VALUES (7);")
            .expect("commit WAL-only rows");
        for suffix in ["", "-wal"] {
            let from = mcp_agent_mail_core::disk::sqlite_sidecar_path(&writer_path, suffix);
            let to = mcp_agent_mail_core::disk::sqlite_sidecar_path(&db_path, suffix);
            std::fs::copy(&from, &to).expect("copy family member while the writer is open");
        }
    }
    let wal = mcp_agent_mail_core::disk::sqlite_sidecar_path(&db_path, "-wal");
    assert!(
        std::fs::metadata(&wal).is_ok_and(|m| m.len() > 32),
        "fixture must keep committed WAL frames"
    );
    assert!(
        mcp_agent_mail_db::pool::open_guarded_read_only_canonical_sqlite_file(&db_path, "probe")
            .is_err(),
        "a WAL without its SHM is the shape the guarded read-only opener cannot serve"
    );
    let family_before: std::collections::BTreeMap<String, Vec<u8>> = std::fs::read_dir(dir.path())
        .expect("list family")
        .flatten()
        .map(|e| {
            (
                e.file_name().to_string_lossy().into_owned(),
                std::fs::read(e.path()).expect("read"),
            )
        })
        .collect();

    let opened = doctor_open_canonical_source_for_diagnostic(&db_path, "resting WAL test")
        .expect("a resting WAL family must be readable through the staged copy");
    assert!(
        matches!(
            opened.kind,
            DoctorCanonicalDiagnosticSourceKind::StagedFamilyCopy
        ),
        "sidecar-free resting WAL family must fall back to the staged copy"
    );
    let rows = opened
        .conn
        .query_sync("SELECT id FROM t", &[])
        .expect("read WAL-only rows from the staged copy");
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].get_named::<i64>("id").unwrap(), 7);
    drop(opened);

    let family_after: std::collections::BTreeMap<String, Vec<u8>> = std::fs::read_dir(dir.path())
        .expect("list family")
        .flatten()
        .map(|e| {
            (
                e.file_name().to_string_lossy().into_owned(),
                std::fs::read(e.path()).expect("read"),
            )
        })
        .collect();
    assert_eq!(
        family_after.keys().collect::<Vec<_>>(),
        family_before.keys().collect::<Vec<_>>(),
        "the staged read must not add or remove source-family files"
    );
    for (name, bytes) in &family_before {
        if name.ends_with("-shm") {
            continue; // SQLite reader bookkeeping may move a read mark (br-00gl8)
        }
        assert_eq!(&family_after[name], bytes, "{name} must be byte-identical");
    }
}

#[test]
fn doctor_read_only_strategy_matches_checkpointed_committed_wal() {
    let writer_dir = tempfile::tempdir().expect("writer directory");
    let hot_dir = tempfile::tempdir().expect("hot family directory");
    let settled_dir = tempfile::tempdir().expect("checkpointed family directory");
    let stale_dir = tempfile::tempdir().expect("main-only control directory");
    let writer_path = writer_dir.path().join("storage.sqlite3");
    let hot_path = hot_dir.path().join("storage.sqlite3");
    let settled_path = settled_dir.path().join("storage.sqlite3");
    let stale_path = stale_dir.path().join("storage.sqlite3");
    seed_project_only_db(&writer_path, "wal-strategy", "/wal-strategy");
    {
        let writer =
            mcp_agent_mail_db::CanonicalDbConn::open_file(writer_path.display().to_string())
                .expect("open private canonical writer");
        writer
            .execute_raw(
                "PRAGMA journal_mode = WAL; PRAGMA wal_autocheckpoint = 0; \
                     ALTER TABLE agents RENAME TO agents_before_wal; \
                     PRAGMA wal_checkpoint(TRUNCATE);",
            )
            .expect("checkpoint a deliberately incomplete schema");
        writer
            .execute_raw(
                "ALTER TABLE agents_before_wal RENAME TO agents; \
                     INSERT INTO projects (id, slug, human_key, created_at) \
                     VALUES (2, 'wal-only', '/wal-only', 0);",
            )
            .expect("commit the schema repair and a row only in WAL");
        for suffix in ["", "-wal"] {
            std::fs::copy(
                sqlite_sidecar_path(&writer_path, suffix),
                sqlite_sidecar_path(&hot_path, suffix),
            )
            .expect("retain the committed family without checkpointing");
        }
    }
    std::fs::copy(&writer_path, &settled_path).expect("copy the checkpointed equivalent");
    std::fs::copy(&hot_path, &stale_path).expect("copy main-only negative control");
    let stale = mcp_agent_mail_db::CanonicalDbConn::open_file(stale_path.display().to_string())
        .expect("open independent main-only control");
    assert!(
        doctor_required_tables_canonical(&stale)
            .expect("inspect stale schema")
            .iter()
            .any(|name| name == "agents"),
        "ignoring WAL must lose a table required by the strategy"
    );
    let stale_rows = stale
        .query_sync("SELECT COUNT(*) AS count FROM projects", &[])
        .expect("read main-only row control");
    assert_eq!(stale_rows[0].get_named::<i64>("count").expect("count"), 1);
    assert!(
        std::fs::metadata(sqlite_sidecar_path(&hot_path, "-wal"))
            .expect("committed WAL exists")
            .len()
            > mcp_agent_mail_db::pool::SQLITE_WAL_HEADER_BYTES
    );

    for path in [&hot_path, &settled_path] {
        let root = path.parent().expect("fixture directory");
        let before = sqlite_family_bytes_for_cli_open_test(path);
        let names_before = directory_entry_names_for_cli_open_test(root);
        let url = format!("sqlite:///{}", path.display());
        let opened =
            open_db_for_doctor_check_read_only_with_context(&url).expect("open diagnostic family");
        let rows = opened
            .conn
            .query_sync("SELECT COUNT(*) AS count FROM projects", &[])
            .expect("read committed rows");
        assert_eq!(rows[0].get_named::<i64>("count").expect("count"), 2);
        drop(opened);
        for strategy in [
            doctor_database_fix_strategy_read_only(&url, root),
            doctor_database_fix_strategy_for_fix(true, &url, root),
        ] {
            let strategy = strategy.expect("read-only strategy");
            assert!(
                matches!(strategy, DoctorDatabaseFixStrategy::None(_)),
                "committed WAL and its checkpointed equivalent must both be healthy: {strategy:?}"
            );
        }
        assert_eq!(sqlite_family_bytes_for_cli_open_test(path), before);
        assert_eq!(directory_entry_names_for_cli_open_test(root), names_before);
    }
}

