#[test]
fn collect_doctor_archive_cheap_probe_matches_full_inventory_on_fixture() {
    let tmp = tempfile::tempdir().unwrap();
    let storage_root = tmp.path().join("storage");

    // Project A: two agents, two canonical messages, one thread digest,
    // and one non-canonical layout file (both scans must skip the latter
    // two).
    let project_a = storage_root.join("projects").join("demo-project");
    let canonical_a = project_a.join("messages").join("2026").join("03");
    std::fs::create_dir_all(&canonical_a).unwrap();
    std::fs::write(
        project_a.join("project.json"),
        r#"{"slug":"demo-project","human_key":"/tmp/demo-project"}"#,
    )
    .unwrap();
    for agent in ["BlueLake", "RiverStone"] {
        let agent_dir = project_a.join("agents").join(agent);
        std::fs::create_dir_all(&agent_dir).unwrap();
        std::fs::write(agent_dir.join("profile.json"), "{}").unwrap();
    }
    std::fs::write(
        canonical_a.join("2026-03-12T00-00-00Z__first__7.md"),
        "---json\n{\"id\":7,\"subject\":\"first\"}\n---\nbody\n",
    )
    .unwrap();
    std::fs::write(
        canonical_a.join("2026-03-13T00-00-00Z__second__8.md"),
        "---json\n{\"id\":8,\"subject\":\"second\"}\n---\nbody\n",
    )
    .unwrap();
    let threads_dir = project_a.join("messages").join("threads");
    std::fs::create_dir_all(&threads_dir).unwrap();
    std::fs::write(threads_dir.join("demo-thread.md"), "digest\n").unwrap();
    std::fs::write(
        project_a.join("messages").join("stray.md"),
        "not canonical\n",
    )
    .unwrap();

    // Project B: no agents, one canonical message.
    let project_b = storage_root.join("projects").join("other-project");
    let canonical_b = project_b.join("messages").join("2026").join("04");
    std::fs::create_dir_all(&canonical_b).unwrap();
    std::fs::write(
        project_b.join("project.json"),
        r#"{"slug":"other-project","human_key":"/tmp/other-project"}"#,
    )
    .unwrap();
    std::fs::write(
        canonical_b.join("2026-04-01T00-00-00Z__third__9.md"),
        "---json\n{\"id\":9,\"subject\":\"third\"}\n---\nbody\n",
    )
    .unwrap();

    let probe = collect_doctor_archive_cheap_probe(&storage_root);
    let inventory = collect_doctor_archive_inventory(&storage_root);

    assert!(!probe.ambiguous, "fixture filenames are all parseable");
    assert_eq!(probe.counts.projects, inventory.projects);
    assert_eq!(probe.counts.agents, inventory.agents);
    // The fixture holds no duplicate message ids, so the cheap file count
    // matches both the raw canonical file count and the deduplicated
    // logical message count of the parsing variant.
    assert_eq!(probe.counts.messages, inventory.canonical_message_files);
    assert_eq!(probe.counts.messages, inventory.messages);
    assert_eq!(probe.counts, inventory.counts());
    assert_eq!(probe.counts.projects, 2);
    assert_eq!(probe.counts.agents, 2);
    assert_eq!(probe.counts.messages, 3);
    // Filename-derived max id and identities must agree with the
    // parsing variant exactly — the robot lag gate relies on both.
    assert_eq!(probe.latest_message_id, inventory.latest_message_id);
    assert_eq!(probe.latest_message_id, Some(9));
    assert_eq!(probe.project_identities, inventory.project_identities);

    // Empty/missing storage roots report the default probe, mirroring
    // the parsing variant's empty-inventory behavior.
    assert_eq!(
        collect_doctor_archive_cheap_probe(&tmp.path().join("missing")).counts,
        DoctorInventoryCounts::default()
    );
}

#[test]
fn db_covers_archive_cheap_probe_only_when_every_signal_agrees() {
    // br-kp1in.18: the canonical-read resolver and the robot lag gate skip
    // the per-message archive parse only on this predicate.
    let identity = DoctorProjectIdentity {
        slug: Some("demo".to_string()),
        human_key: Some("/tmp/demo".to_string()),
    };
    let probe = DoctorArchiveCheapProbe {
        counts: DoctorInventoryCounts {
            projects: 1,
            agents: 2,
            messages: 10,
        },
        latest_message_id: Some(10),
        project_identities: std::collections::BTreeSet::from([identity.clone()]),
        ambiguous: false,
    };
    let db = DoctorDbInventory {
        counts: DoctorInventoryCounts {
            projects: 1,
            agents: 2,
            messages: 12,
        },
        max_message_id: 12,
        project_identities: std::collections::BTreeSet::from([identity]),
    };
    assert!(doctor_db_covers_archive_cheap_probe(&probe, &db));

    let ambiguous = DoctorArchiveCheapProbe {
        ambiguous: true,
        ..probe.clone()
    };
    assert!(!doctor_db_covers_archive_cheap_probe(&ambiguous, &db));
    let newer_archive_id = DoctorArchiveCheapProbe {
        latest_message_id: Some(13),
        ..probe.clone()
    };
    assert!(!doctor_db_covers_archive_cheap_probe(
        &newer_archive_id,
        &db
    ));
    let more_archive_files = DoctorArchiveCheapProbe {
        counts: DoctorInventoryCounts {
            messages: 13,
            ..probe.counts.clone()
        },
        ..probe.clone()
    };
    assert!(!doctor_db_covers_archive_cheap_probe(
        &more_archive_files,
        &db
    ));
    let foreign_project = DoctorArchiveCheapProbe {
        project_identities: std::collections::BTreeSet::from([DoctorProjectIdentity {
            slug: Some("other".to_string()),
            human_key: Some("/tmp/other".to_string()),
        }]),
        ..probe.clone()
    };
    assert!(!doctor_db_covers_archive_cheap_probe(&foreign_project, &db));
    let empty_db = DoctorDbInventory::default();
    assert!(!doctor_db_covers_archive_cheap_probe(
        &DoctorArchiveCheapProbe::default(),
        &empty_db
    ));
}

#[test]
fn collect_doctor_archive_cheap_probe_flags_unparsable_canonical_filename_as_ambiguous() {
    let tmp = tempfile::tempdir().unwrap();
    let project = tmp.path().join("projects").join("demo-project");
    let canonical = project.join("messages").join("2026").join("03");
    std::fs::create_dir_all(&canonical).unwrap();
    std::fs::write(canonical.join("no-id-suffix.md"), "body\n").unwrap();

    let probe = collect_doctor_archive_cheap_probe(tmp.path());
    assert_eq!(probe.counts.messages, 1, "layout filters still count it");
    assert!(
        probe.ambiguous,
        "a canonical-layout file with no __<id> suffix must force the full-inventory fallback"
    );
    assert_eq!(probe.latest_message_id, None);
}

#[test]
fn doctor_archive_db_drift_data_loss_classification_gh217() {
    // Metadata-only surplus (extra archive projects/agents, no message
    // drift) is hygiene debt, NOT a data-loss incident.
    let hygiene_archive = DoctorArchiveInventory {
        projects: 73,
        agents: 10,
        messages: 5,
        latest_message_id: Some(9),
        ..DoctorArchiveInventory::default()
    };
    let hygiene_db = DoctorDbInventory {
        counts: DoctorInventoryCounts {
            projects: 32,
            agents: 8,
            messages: 5,
        },
        max_message_id: 9,
        project_identities: std::collections::BTreeSet::new(),
    };
    assert!(!doctor_archive_db_drift_is_data_loss_class(
        &hygiene_archive,
        &hygiene_db
    ));

    // Archive messages ahead of DB → data-loss class.
    let loss_archive = DoctorArchiveInventory {
        projects: 1,
        agents: 1,
        messages: 10,
        latest_message_id: Some(10),
        ..DoctorArchiveInventory::default()
    };
    let loss_db = DoctorDbInventory {
        counts: DoctorInventoryCounts {
            projects: 1,
            agents: 1,
            messages: 7,
        },
        max_message_id: 7,
        project_identities: std::collections::BTreeSet::new(),
    };
    assert!(doctor_archive_db_drift_is_data_loss_class(
        &loss_archive,
        &loss_db
    ));

    // Latest message id ahead (counts equal) → data-loss class.
    let id_ahead_archive = DoctorArchiveInventory {
        projects: 1,
        agents: 1,
        messages: 7,
        latest_message_id: Some(12),
        ..DoctorArchiveInventory::default()
    };
    assert!(doctor_archive_db_drift_is_data_loss_class(
        &id_ahead_archive,
        &loss_db
    ));
}

