#[test]
fn normal_runtime_crate_manifests_route_frankensqlite_through_sqlmodel_adapter() {
    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("workspace root");

    let db_manifest_path = workspace_root
        .join("crates")
        .join("mcp-agent-mail-db")
        .join("Cargo.toml");
    let db_manifest = std::fs::read_to_string(&db_manifest_path)
        .unwrap_or_else(|err| panic!("read {}: {err}", db_manifest_path.display()));
    assert!(
        db_manifest.contains("sqlmodel-frankensqlite.workspace = true"),
        "{} must route normal mailbox DB traffic through SQLModel's FrankenSQLite adapter",
        db_manifest_path.display()
    );
    assert!(
        !db_manifest.contains("fsqlite-core.workspace"),
        "{} must not depend on fsqlite-core directly",
        db_manifest_path.display()
    );
    // The db crate may depend on `fsqlite` directly for engine-boundary
    // utilities (namespace sidecar bindings, FrankenError classification,
    // file identity); what must not happen is opening mailbox connections
    // outside the sqlmodel adapter (br-0dw2c).
    let db_src = workspace_root
        .join("crates")
        .join("mcp-agent-mail-db")
        .join("src");
    let mut offenders = Vec::new();
    let mut pending = vec![db_src];
    while let Some(dir) = pending.pop() {
        for entry in std::fs::read_dir(&dir).expect("read db src dir").flatten() {
            let path = entry.path();
            if path.is_dir() {
                pending.push(path);
                continue;
            }
            if path.extension().and_then(|e| e.to_str()) != Some("rs") {
                continue;
            }
            let source = std::fs::read_to_string(&path).expect("read db source");
            for (line_no, line) in source.lines().enumerate() {
                let trimmed = line.trim_start();
                if trimmed.starts_with("//") {
                    continue;
                }
                if trimmed.contains("fsqlite::Connection::open")
                    || trimmed.contains("fsqlite::open(")
                    || trimmed.contains("fsqlite::Database::open")
                {
                    offenders.push(format!("{}:{}", path.display(), line_no + 1));
                }
            }
        }
    }
    assert!(
        offenders.is_empty(),
        "mailbox connections must be opened through sqlmodel-frankensqlite, not fsqlite directly: {offenders:?}"
    );

    for crate_name in [
        "mcp-agent-mail-cli",
        "mcp-agent-mail-server",
        "mcp-agent-mail-tools",
    ] {
        let manifest_path = workspace_root
            .join("crates")
            .join(crate_name)
            .join("Cargo.toml");
        let manifest = std::fs::read_to_string(&manifest_path)
            .unwrap_or_else(|err| panic!("read {}: {err}", manifest_path.display()));
        for forbidden_name in ["sqlmodel-frankensqlite", "fsqlite", "fsqlite-core"] {
            assert!(
                !manifest.contains(forbidden_name),
                "{} must use mcp-agent-mail-db as the SQLite boundary, not depend on `{}` directly",
                manifest_path.display(),
                forbidden_name
            );
        }
    }
}

