/// br-2hpuk: a family whose committed data lives only in its WAL (main
/// file empty or missing) is an existing mailbox too. The initializing
/// open would recover it, so a refused read must not fall back to it.
#[test]
fn read_verb_mailbox_is_initialized_counts_wal_only_families() {
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("wal-only.sqlite3");
    let db_url = format!("sqlite:///{}", db_path.display());
    assert!(!read_verb_mailbox_is_initialized(&db_url), "missing family");
    std::fs::write(&db_path, b"").expect("empty main");
    assert!(
        !read_verb_mailbox_is_initialized(&db_url),
        "empty main only"
    );
    let wal = dir.path().join("wal-only.sqlite3-wal");
    std::fs::write(&wal, b"").expect("empty wal");
    assert!(
        !read_verb_mailbox_is_initialized(&db_url),
        "empty main and wal"
    );
    std::fs::write(&wal, [0x37_u8, 0x7f, 0x06, 0x82]).expect("non-empty wal");
    assert!(
        read_verb_mailbox_is_initialized(&db_url),
        "empty main, data in wal"
    );
    std::fs::remove_file(&db_path).expect("remove main");
    assert!(
        read_verb_mailbox_is_initialized(&db_url),
        "missing main, data in wal"
    );
    std::fs::remove_file(&wal).expect("remove wal");
    std::fs::write(dir.path().join("wal-only.sqlite3-journal"), b"journal").expect("hot journal");
    assert!(
        read_verb_mailbox_is_initialized(&db_url),
        "hot rollback journal"
    );
}

/// br-2hpuk: a robot read once applied a schema migration to a live
/// mailbox by falling back to the initializing open. An existing mailbox
/// that the read-only admission refuses must be left byte-for-byte alone.
#[test]
fn robot_reads_never_migrate_an_existing_older_schema_mailbox() {
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("older-schema.sqlite3");
    let db_url = format!("sqlite:///{}", db_path.display());
    {
        let seed =
            mcp_agent_mail_db::CanonicalDbConn::open_file(db_path.to_string_lossy().as_ref())
                .expect("open seed db");
        for stmt in [
            "CREATE TABLE projects (id INTEGER PRIMARY KEY, slug TEXT NOT NULL, human_key TEXT NOT NULL, created_at DATETIME NOT NULL)",
            "CREATE TABLE agents (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, name TEXT NOT NULL)",
            "INSERT INTO projects (id, slug, human_key, created_at) VALUES (1, 'old', '/tmp/old', '2026-09-01 00:00:00')",
        ] {
            seed.execute_raw(stmt).expect("seed statement");
        }
    }
    let schema_of = |path: &std::path::Path| {
        let conn = mcp_agent_mail_db::CanonicalDbConn::open_file(path.to_string_lossy().as_ref())
            .expect("open for inspection");
        conn.query_sync(
            "SELECT type, name, COALESCE(sql, '') AS sql FROM sqlite_master ORDER BY type, name",
            &[],
        )
        .expect("read sqlite_master")
        .iter()
        .map(|row| {
            (
                row.get_named::<String>("type").unwrap(),
                row.get_named::<String>("name").unwrap(),
                row.get_named::<String>("sql").unwrap(),
            )
        })
        .collect::<Vec<_>>()
    };
    let before = schema_of(&db_path);

    for (verb, result) in [
        (
            "robot read",
            open_db_sync_robot_with_database_url(&db_url).map(drop),
        ),
        (
            "robot attachments read",
            open_db_sync_robot_attachments_with_database_url(&db_url).map(drop),
        ),
    ] {
        let error = result.expect_err("an older-schema mailbox must not be opened by migrating it");
        let message = error.to_string();
        assert!(
            message.contains(verb) && message.contains("never migrate"),
            "{verb}: {message}"
        );
    }

    assert_eq!(
        schema_of(&db_path),
        before,
        "a robot read changed the mailbox schema or migration ledger"
    );
}

#[test]
fn open_db_sync_robot_attachments_with_database_url_falls_back_under_reserved_lock() {
    let dir = tempfile::tempdir().expect("tempdir");
    let db_path = dir.path().join("robot-attachments-fallback.sqlite3");
    let db_url = format!("sqlite:///{}", db_path.display());
    let db_path_str = db_path.to_string_lossy().into_owned();

    let seed_conn = mcp_agent_mail_db::DbConn::open_file(&db_path_str).expect("open seed db");
    for stmt in [
        "PRAGMA foreign_keys = OFF",
        "CREATE TABLE projects (id INTEGER PRIMARY KEY, slug TEXT NOT NULL, human_key TEXT NOT NULL)",
        "CREATE TABLE agents (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, name TEXT NOT NULL)",
        "CREATE TABLE messages (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL, sender_id INTEGER NOT NULL, subject TEXT NOT NULL, attachments TEXT NOT NULL DEFAULT '[]', created_ts DATETIME NOT NULL)",
        "INSERT INTO projects (id, slug, human_key) VALUES (1, 'robot-attachments-lock', '/tmp/robot-attachments-lock')",
        "INSERT INTO agents (id, project_id, name) VALUES (1, 1, 'AttachReader')",
        "INSERT INTO messages (id, project_id, sender_id, subject, attachments, created_ts) VALUES (1, 1, 1, 'artifact', '[\"bundle.zip\"]', '2026-03-12 11:00:00')",
    ] {
        seed_conn.execute_raw(stmt).expect("seed statement");
    }
    drop(seed_conn);

    let (ready_tx, ready_rx) = std::sync::mpsc::sync_channel(1);
    let (release_tx, release_rx) = std::sync::mpsc::sync_channel(1);
    let lock_path = db_path_str.clone();
    let lock_thread = std::thread::spawn(move || {
        let lock_conn = mcp_agent_mail_db::DbConn::open_file(&lock_path).expect("open lock db");
        lock_conn
            .execute_raw("PRAGMA busy_timeout = 1;")
            .expect("set lock busy_timeout");
        lock_conn
            .execute_raw("BEGIN IMMEDIATE")
            .expect("hold reserved sqlite lock");
        ready_tx.send(()).expect("signal lock ready");
        release_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .expect("wait for release");
        lock_conn
            .execute_raw("ROLLBACK")
            .expect("release sqlite lock");
    });

    ready_rx
        .recv_timeout(std::time::Duration::from_secs(1))
        .expect("wait for lock thread");

    let (result_tx, result_rx) = std::sync::mpsc::sync_channel(1);
    let open_url = db_url.clone();
    let open_thread = std::thread::spawn(move || {
        let result = open_db_sync_robot_attachments_with_database_url(&open_url).and_then(|conn| {
            conn.query_sync("SELECT COUNT(*) AS c FROM messages", &[])
                .map_err(|e| CliError::Other(format!("messages count failed: {e}")))
                .map(|rows| {
                    rows.first()
                        .and_then(|row| row.get_named::<i64>("c").ok())
                        .unwrap_or(0)
                })
        });
        result_tx.send(result).expect("send open result");
    });

    let result = result_rx.recv_timeout(std::time::Duration::from_secs(1));
    // Retire the fixture workers on error as well as timeout before an
    // assertion can unwind and drop their database or release channel.
    let release = release_tx.send(());
    let reader_join = open_thread.join();
    let writer_join = lock_thread.join();
    assert!(
        release.is_ok() && reader_join.is_ok() && writer_join.is_ok(),
        "robot result={result:?}; release={release:?}; reader joined={}; writer joined={}",
        reader_join.is_ok(),
        writer_join.is_ok(),
    );
    let message_count = result
        .expect("robot attachments open should not wait for canonical init under reserved lock")
        .expect("robot attachments helper should fall back to read-only open");
    assert_eq!(
        message_count, 1,
        "robot attachments fallback should preserve readable attachment rows"
    );
}

